// Comprime un'immagine caricata (es. foto di un documento) in un JPEG
// leggero prima di salvarla, per non far esplodere lo storage.
function fileToCompressedDataURL(file, maxWidth = 1000, quality = 0.7) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const img = new Image();
      img.onload = () => {
        const scale = Math.min(1, maxWidth / img.width);
        const canvas = document.createElement("canvas");
        canvas.width = img.width * scale;
        canvas.height = img.height * scale;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL("image/jpeg", quality));
      };
      img.onerror = reject;
      img.src = reader.result;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

function bookingsToCSV(bookings, rooms) {
  const header = ["Camera", "Ospite", "Email", "Telefono", "Ospiti", "Check-in", "Check-out", "Stato", "Pagato"];
  const rows = bookings
    .filter((b) => !b.isBlock)
    .map((b) => [
      roomName(rooms, b.roomId), b.guest, b.email, b.phone || "", b.guests || "",
      b.checkin, b.checkout, b.status, b.paid ? "sì" : "no",
    ]);
  const escape = (v) => `"${String(v).replace(/"/g, '""')}"`;
  return [header, ...rows].map((r) => r.map(escape).join(",")).join("\r\n");
}

function downloadCSV(bookings, rooms) {
  const csv = bookingsToCSV(bookings, rooms);
  const blob = new Blob(["\uFEFF" + csv], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = "prenotazioni-da-nonna-peppa.csv";
  a.click();
  URL.revokeObjectURL(url);
}

/* ---------- invio email automatico (EmailJS, senza backend) ----------
Per attivare l'invio automatico:
1) crea un account gratuito su https://www.emailjs.com
2) collega il tuo indirizzo email come "Email Service" e copia il Service ID
3) crea un "Email Template": nel campo "To Email" delle impostazioni del
   template metti {{to_email}}; nel corpo usa queste variabili al posto
   delle parentesi quadre del tuo testo:
     {{guest_name}}      al posto di [Nome dell'Ospite] / [Nome Cognome]
     {{checkin_date}}    al posto di [Data Check-in]
     {{checkin_time}}    al posto di [Ora Check-in]
     {{checkout_date}}   al posto di [Data Check-out]
     {{checkout_time}}   al posto di [Ora Check-out]
     {{guests_count}}    al posto di [Numero Ospiti]
     {{address}}         al posto di [Indirizzo della struttura]
     {{host_name}}       al posto di [Tuo Nome]
     {{host_phone}}      al posto di [Tuo Numero]
     {{host_email}}      al posto di [Tua Email]
   poi salva e copia il Template ID (in alto nella pagina del template)
4) in Account > General copia la Public Key
5) incolla i tre valori qui sotto: finché restano vuoti, l'app userà
   comunque il pulsante manuale (mailto) come ora, senza rompersi.
------------------------------------------------------------------------ */
const EMAILJS_SERVICE_ID = "service_ts5fsru";
const EMAILJS_TEMPLATE_ID = "template_jmleq78";       // conferma
const EMAILJS_TEMPLATE_ID_REJECT = "template_ik9mx2j"; // rifiuto/cancellazione
const EMAILJS_PUBLIC_KEY = "WMUaBvr7B0AolwIcr";

let emailjsLoaded = false;

const emailAutoConfigured = (templateId = EMAILJS_TEMPLATE_ID) =>
  Boolean(EMAILJS_SERVICE_ID && templateId && EMAILJS_PUBLIC_KEY);

// Chiamiamo direttamente l'API di EmailJS via fetch invece di caricare il
// loro script da un CDN esterno: più affidabile, niente dipendenza da un
// URL di terze parti che potrebbe non essere raggiungibile da qui.
async function sendAutoEmail(templateParams, templateId = EMAILJS_TEMPLATE_ID) {
  if (!emailAutoConfigured(templateId)) return { sent: false, reason: "not-configured" };
  try {
    const res = await fetch("https://api.emailjs.com/api/v1.0/email/send", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        service_id: EMAILJS_SERVICE_ID,
        template_id: templateId,
        user_id: EMAILJS_PUBLIC_KEY,
        template_params: templateParams,
      }),
    });
    if (!res.ok) {
      const detail = await res.text().catch(() => "");
      console.error("EmailJS ha risposto con errore:", res.status, detail);
      return { sent: false, reason: "error", detail: `${res.status} ${detail}`.trim() };
    }
    return { sent: true };
  } catch (e) {
    console.error("invio email automatico fallito", e);
    return { sent: false, reason: "error", detail: e.message };
  }
}

function buildICS(room, bookings) {
  const lines = [
    "BEGIN:VCALENDAR",
    "VERSION:2.0",
    "PRODID:-//Da Nonna Peppa//" + room.name + "//IT",
  ];
  bookings
    .filter((b) => b.roomId === room.id && b.status === "confermata")
    .forEach((b) => {
      lines.push(
        "BEGIN:VEVENT",
        `UID:${b.id}@dananonapeppa`,
        `DTSTART;VALUE=DATE:${b.checkin.replace(/-/g, "")}`,
        `DTEND;VALUE=DATE:${b.checkout.replace(/-/g, "")}`,
        `SUMMARY:Occupata - ${b.guest}`,
        "END:VEVENT"
      );
    });
  lines.push("END:VCALENDAR");
  return lines.join("\r\n");
}

async function storageGet(key, fallback, shared = true) {
  try {
    const res = await window.storage.get(key, shared);
    return res ? JSON.parse(res.value) : fallback;
  } catch {
    return fallback;
  }
}
async function storageSet(key, value, shared = true) {
  try {
    await window.storage.set(key, JSON.stringify(value), shared);
  } catch (e) {
    console.error("storage set failed", e);
  }
}

