function SunflowerSeal({ size = 40 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 40 40" className="seal">
      <g fill="none" stroke="#B8935A" strokeWidth="1.4">
        {[...Array(10)].map((_, i) => {
          const angle = (i * Math.PI * 2) / 10;
          const x1 = 20 + Math.cos(angle) * 7;
          const y1 = 20 + Math.sin(angle) * 7;
          const x2 = 20 + Math.cos(angle) * 17;
          const y2 = 20 + Math.sin(angle) * 17;
          return <ellipse key={i} cx={(x1 + x2) / 2} cy={(y1 + y2) / 2} rx="4" ry="7"
            transform={`rotate(${(angle * 180) / Math.PI + 90} ${(x1 + x2) / 2} ${(y1 + y2) / 2})`} />;
        })}
      </g>
      <circle cx="20" cy="20" r="6.5" fill="#C97B4A" />
    </svg>
  );
}

function PinGate({ adminPin, onUnlock, onBack }) {
  const [val, setVal] = useState("");
  const [error, setError] = useState("");

  const submit = () => {
    if (val === adminPin) {
      onUnlock();
    } else {
      setError("PIN errato. Riprova.");
      setVal("");
    }
  };

  return (
    <div className="max-w-sm mx-auto px-4 py-16 text-center">
      <SunflowerSeal size={40} />
      <h2 className="display text-2xl mt-3 mb-1">Area gestore</h2>
      <p className="text-sm mb-5" style={{ color: "#8A7A64" }}>
        Inserisci il PIN per accedere alla gestione della struttura.
      </p>
      <input
        type="password"
        inputMode="numeric"
        value={val}
        onChange={(e) => { setVal(e.target.value); setError(""); }}
        onKeyDown={(e) => e.key === "Enter" && submit()}
        placeholder="PIN"
        className="dnp-input2 text-center text-lg tracking-widest"
        style={{ maxWidth: 180, margin: "0 auto" }}
        autoFocus
      />
      {error && <p className="text-sm mt-2" style={{ color: "#B04A3B" }}>{error}</p>}
      <button onClick={submit} className="mt-4 px-6 py-2 rounded-full text-sm block mx-auto"
        style={{ background: "#362B22", color: "#fff" }}>
        Entra
      </button>
      <button onClick={onBack} className="mt-3 text-xs underline block mx-auto" style={{ color: "#8A7A64" }}>
        Torna al sito
      </button>
      <style>{`.dnp-input2{ padding:10px 12px; border-radius:10px; border:1px solid #E4D9C3; font-size:14px; outline:none; } .dnp-input2:focus{ border-color:#B8935A; }`}</style>
    </div>
  );
}

