function StaffPortal({ employees, bookings, rooms, saveBookings, showToast, onLock }) {
  const [me, setMe] = useState(null);
  const seenTaskIds = React.useRef(new Set());

  // Avviso sonoro + notifica quando compare un nuovo incarico assegnato a
  // "me", mentre questa pagina resta aperta (stesso limite spiegato per il
  // gestore: ad app chiusa serve il passo successivo con notifiche push vere).
  useEffect(() => {
    if (!me) return;
    if ("Notification" in window && Notification.permission === "default") {
      Notification.requestPermission();
    }
    const myTasks = getTasksForEmployee(bookings, rooms, me.id);
    myTasks.forEach((t) => seenTaskIds.current.add(t.id));
  }, [me]);

  useEffect(() => {
    if (!me) return;
    const interval = setInterval(async () => {
      const latest = await storageGet("dnp-bookings", bookings, true);
      const myTasks = getTasksForEmployee(latest, rooms, me.id);
      const fresh = myTasks.filter((t) => !seenTaskIds.current.has(t.id));
      if (fresh.length > 0) {
        fresh.forEach((t) => seenTaskIds.current.add(t.id));
        try {
          const Ctx = window.AudioContext || window.webkitAudioContext;
          const ctx = new Ctx();
          const o = ctx.createOscillator();
          const g = ctx.createGain();
          o.connect(g); g.connect(ctx.destination);
          o.frequency.value = 660;
          g.gain.setValueAtTime(0.001, ctx.currentTime);
          g.gain.exponentialRampToValueAtTime(0.2, ctx.currentTime + 0.02);
          g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.5);
          o.start(); o.stop(ctx.currentTime + 0.5);
        } catch {}
        if ("Notification" in window && Notification.permission === "granted") {
          new Notification("Nuovo incarico", { body: fresh[0].label });
        }
        showToast("Ti è stato assegnato un nuovo incarico");
      }
    }, 15000);
    return () => clearInterval(interval);
  }, [me, bookings, rooms]);

  if (!me) {
    return (
      <div className="max-w-sm mx-auto px-4 py-16 text-center">
        <SunflowerSeal size={40} />
        <h2 className="display text-2xl mt-3 mb-4">Chi sei?</h2>
        {employees.length === 0 ? (
          <p className="text-sm" style={{ color: "#8A7A64" }}>
            Nessun membro dello staff è stato ancora aggiunto. Chiedi a Nonna Peppa di aggiungerti dal pannello Gestione → Personale.
          </p>
        ) : (
          <div className="space-y-2">
            {employees.map((e) => (
              <button key={e.id} onClick={() => setMe(e)}
                className="w-full py-3 rounded-full text-sm"
                style={{ background: "#fff", border: "1px solid #E4D9C3" }}>
                {e.name}
              </button>
            ))}
          </div>
        )}
        <button onClick={onLock} className="mt-5 text-xs underline" style={{ color: "#8A7A64" }}>
          Torna al sito
        </button>
      </div>
    );
  }

  const myTasks = getTasksForEmployee(bookings, rooms, me.id).sort((a, b) => a.date.localeCompare(b.date));
  const pending = myTasks.filter((t) => !t.done);
  const done = myTasks.filter((t) => t.done);

  const markDone = async (task) => {
    const next = bookings.map((b) => {
      if (b.id !== task.bookingId) return b;
      return task.kind === "prep" ? { ...b, prepDone: true } : { ...b, cleanDone: true };
    });
    await saveBookings(next);
    showToast("Incarico segnato come completato");
  };

  return (
    <div className="max-w-2xl mx-auto px-4 py-6">
      <div className="flex items-center justify-between mb-4">
        <div>
          <p className="text-xs" style={{ color: "#8A7A64" }}>Bentornato/a</p>
          <p className="display text-xl">{me.name}</p>
        </div>
        <button onClick={() => setMe(null)} className="text-xs px-2.5 py-1 rounded-full"
          style={{ background: "#F1E8D6", color: "#362B22" }}>
          Cambia utente
        </button>
      </div>

      <h3 className="display text-lg mb-2">Da fare</h3>
      {pending.length === 0 ? (
        <Empty text="Nessun incarico in sospeso al momento." />
      ) : (
        <div className="space-y-3 mb-6">
          {pending.map((t) => (
            <div key={t.id} className="rounded-xl p-4 bg-white flex items-center justify-between" style={{ border: "1px solid #E4D9C3" }}>
              <div>
                <span className="text-xs px-2 py-0.5 rounded-full" style={{ background: t.kind === "prep" ? "#B8935A22" : "#C97B4A22", color: t.kind === "prep" ? "#B8935A" : "#C97B4A" }}>
                  {t.kind === "prep" ? "Preparazione" : "Pulizia"}
                </span>
                <p className="font-medium mt-1">{t.label}</p>
                <p className="text-xs" style={{ color: "#8A7A64" }}>{fmt(t.date)}</p>
              </div>
              <button onClick={() => markDone(t)} className="px-3 py-1.5 rounded-full text-xs shrink-0"
                style={{ background: "#7C8B6F", color: "#fff" }}>
                Fatto
              </button>
            </div>
          ))}
        </div>
      )}

      {done.length > 0 && (
        <>
          <h3 className="display text-lg mb-2" style={{ color: "#8A7A64" }}>Completati</h3>
          <div className="space-y-2">
            {done.map((t) => (
              <div key={t.id} className="flex items-center justify-between text-sm px-3 py-2 rounded-lg bg-white" style={{ border: "1px solid #E4D9C3" }}>
                <span>{t.label}</span>
                <span style={{ color: "#7C8B6F" }}>✓ {t.paid ? "pagato" : "in attesa di pagamento"}</span>
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

// Ricava la lista di incarichi (preparazione/pulizia) assegnati a un dipendente
// a partire dalle prenotazioni confermate.
function getTasksForEmployee(bookings, rooms, employeeId) {
  const tasks = [];
  bookings
    .filter((b) => b.status === "confermata")
    .forEach((b) => {
      const rName = roomName(rooms, b.roomId);
      if (b.prepEmployee === employeeId) {
        tasks.push({
          id: `${b.id}-prep`,
          bookingId: b.id,
          kind: "prep",
          label: `Prepara ${rName} — arrivo di ${b.guest}`,
          date: b.checkin,
          done: !!b.prepDone,
          paid: !!b.prepPaid,
        });
      }
      if (b.cleanEmployee === employeeId) {
        tasks.push({
          id: `${b.id}-clean`,
          bookingId: b.id,
          kind: "clean",
          label: `Pulisci ${rName} — dopo partenza di ${b.guest}`,
          date: b.checkout,
          done: !!b.cleanDone,
          paid: !!b.cleanPaid,
        });
      }
    });
  return tasks;
}

